-- Helpers and colors used by more than one extra
local repo_root =
	vim.fn.fnamemodify(debug.getinfo(1, 'S').source:sub(2), ':p:h:h:h')
package.path = repo_root .. '/lua/?.lua;' .. package.path

local palette = require('cutiepro.palette')

local M = {}

M.repo_root = repo_root
M.palette = palette
M.terminal_colors = palette.terminal_colors

M.generated_note =
	'Generated by scripts/build-extras.lua from lua/cutiepro/palette.lua, do not edit'

-- The palette color behind each role the terminal extras share
M.theme = {
	foreground = palette.foreground,
	background = palette.background,
	cursor = palette.accent,
	selection_foreground = palette.foreground,
	selection_background = palette.background_selection,
	split = palette.border,
}

function M.join_lines(lines)
	return table.concat(lines, '\n') .. '\n'
end

-- One hex per line, wrapped in quotes and followed by a comma
function M.quoted_hex_lines(hexes, indent, quote)
	local lines = {}
	for _, hex in ipairs(hexes) do
		table.insert(lines, indent .. quote .. hex .. quote .. ',')
	end
	return lines
end

function M.read_file(path)
	local file = io.open(path, 'r')
	if not file then
		return nil
	end
	local content = file:read('*a')
	file:close()
	return content
end

function M.write_file(path, content)
	vim.fn.mkdir(vim.fs.dirname(path), 'p')
	local file = assert(io.open(path, 'w'))
	file:write(content)
	file:close()
end

return M
